import{_ as e,c as a,a2 as p,o as _}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第一百零四章 眼睛看到外界事物生起眼触","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/104第一百零四章 眼睛看到外界事物生起眼触.md","filePath":"meditation/巴利文大藏经/104第一百零四章 眼睛看到外界事物生起眼触.md"}'),o={name:"meditation/巴利文大藏经/104第一百零四章 眼睛看到外界事物生起眼触.md"};function r(n,t,i,s,d,c){return _(),a("div",null,t[0]||(t[0]=[p('<h1 id="第一百零四章-眼睛看到外界事物生起眼触" tabindex="-1">第一百零四章 眼睛看到外界事物生起眼触 <a class="header-anchor" href="#第一百零四章-眼睛看到外界事物生起眼触" aria-label="Permalink to &quot;第一百零四章 眼睛看到外界事物生起眼触&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部14相应2经/种种触经(界相应/因缘篇/修多罗)</p><p>有个时候，佛陀住在舍卫城的祇树林给孤独园。有一天，佛陀对出家弟子们说：“弟子们，以种种界（界解释，见第一百零三章）为前提条件就会生起种种触。弟子们，什么是种种界呢？就是：眼界、耳界、鼻界、舌界、身界、意界（眼界、耳界、鼻界、舌界、身界、意界解释，见第一百零三章），弟子们，这就是种种界。</p><p>弟子们，什么是以种种界为前提条件就会生起种种触呢？就是：当眼睛与事物相遇的时候，通过光线的传递就会分别出外界事物的存在和不同，并且产生对外界事物的认知，这就是眼触，也就是以眼界为前提条件就会生起眼触。</p><p>当耳朵与声音相遇的时候，通过各种介质的传递就会分别出外界声音的存在和不同，并且产生对外界声音的认知，这就是耳触，也就是以耳界为前提条件就会生起耳触。</p><p>当鼻子与气味相遇的时候，通过各种介质的传递就会分别出外界气味的存在和不同，并且产生对外界气味的认知，这就是鼻触，也就是以鼻界为前提条件就会生起鼻触。</p><p>当舌头与味道相遇的时候，就会分别出外界味道的存在和不同，并且产生对外界味道的认知，这就是舌触，也就是以舌界为前提条件就会生起舌触。</p><p>当身体触摸到事物、感受到环境变化（冷热、舒适等等环境）的时候，就会分别出事物触摸感觉、环境变化感觉的存在和不同，并且产生对事物触摸感觉、环境变化感觉的认知。</p><p>当内心与物质事物、精神思想相遇的时候，就会分别出外界物质事物、精神思想的存在和不同，并且产生对外界物质事物、精神思想的认知开始思索，这就是意触，也就是以意界为前提条件就会生起意触。</p><p>弟子们，这就是以种种界为前提条件就会生起种种触的法义。”</p><p>佛陀说法后，听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。</p>',12)]))}const f=e(o,[["render",r]]);export{m as __pageData,f as default};
